def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            mode = data["rounding"]
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}

    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            choices.append([None] + [row["version"] for row in packages[name]])

        best_vector = None
        best_versions = None
        for assignment in product(*choices):
            selected = {name: version for name, version in zip(names, assignment)
                        if version is not None}
            if any(name not in selected or not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            if any(version in blocked.get(name, [])
                   for name, version in selected.items()):
                continue
            if any(name in selected and selected[name] != version
                   for name, version in pins.items()):
                continue

            edges = {name: [] for name in selected}
            valid = True
            for name, version in selected.items():
                row = next(row for row in packages[name]
                           if row["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    dep_version = selected.get(dep_name)
                    if dep_version is None or not dep["min"] <= dep_version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(dep_name)
                if not valid:
                    break
            if not valid:
                continue

            # Every installed package must be reachable from a root.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(selected):
                continue

            finished, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in edges):
                continue

            vector = tuple(selected.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best_versions = vector, selected

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}

    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = bit.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        start_time = data["start"]
        distances = {start_state: start_time}
        queue = [(start_time, source, initial_mask, data["coupons"])]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                next_mask = mask | bit.get(edge["v"], 0)
                for duration, next_remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, edge["v"],
                                               next_mask, next_remaining))
        return {"arrival": None}

    return solve


